{
    $user = User::factory()->create();
    $year = AcademicYear::create([
        'name' => '2026-2027',
        'start_date' => today()->toDateString(),
        'end_date' => today()->addMonths(9)->toDateString(),
        'is_active' => false,
    ]);

    $response = $this->actingAs($user)->patch("/academic-years/{$year->id}/toggle-close");

