/**
 * PWA — Les Rois du Sahel.
 *
 * 1. Enregistre le service worker (HTTPS ou localhost requis).
 * 2. Propose AUTOMATIQUEMENT l'installation via une bannière :
 *    - Chrome / Edge / Samsung Internet : événement `beforeinstallprompt`
 *      → bouton « 📲 Installer » qui déclenche la vraie invite du navigateur.
 *    - iPhone / iPad (Safari) : pas d'invite programmable → la bannière
 *      affiche le mode d'emploi « Partager → Sur l'écran d'accueil ».
 *    - déjà installé (mode standalone) : bannière jamais affichée.
 * 3. La bannière refusée (« Plus tard ») réapparaît après 7 jours.
 */
(function () {
    'use strict';

    // Service worker : HTTPS ou localhost uniquement.
    if ('serviceWorker' in navigator && (location.protocol === 'https:' || ['localhost', '127.0.0.1'].includes(location.hostname))) {
        window.addEventListener('load', () => {
            navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(() => {});
        });
    }

    const SNOOZE_KEY = 'rds-pwa-install-dismissed-at';
    const SNOOZE_MS = 7 * 24 * 60 * 60 * 1000;
    let deferredPrompt = null;

    function isStandalone() {
        return window.matchMedia('(display-mode: standalone)').matches
            || window.navigator.standalone === true
            || document.referrer.startsWith('android-app://');
    }

    function isSnoozed() {
        const at = parseInt(localStorage.getItem(SNOOZE_KEY) || '0', 10);
        return Date.now() - at < SNOOZE_MS;
    }

    function isIos() {
        return /iphone|ipad|ipod/i.test(navigator.userAgent) && !('BeforeInstallPromptEvent' in window);
    }

    function banner() {
        return document.getElementById('pwa-install-banner');
    }

    function showBanner() {
        const el = banner();
        if (!el || isStandalone() || isSnoozed()) {
            return;
        }
        if (isIos()) {
            el.querySelector('[data-pwa-android]').hidden = true;
            el.querySelector('[data-pwa-ios]').hidden = false;
        }
        el.hidden = false;
    }

    function hideBanner(snooze) {
        const el = banner();
        if (el) {
            el.hidden = true;
        }
        if (snooze) {
            try {
                localStorage.setItem(SNOOZE_KEY, String(Date.now()));
            } catch (e) { /* stockage indisponible : on réessaiera */ }
        }
    }

    // Chrome/Edge : l'application propose son installation dès que le navigateur l'autorise.
    window.addEventListener('beforeinstallprompt', (event) => {
        event.preventDefault();
        deferredPrompt = event;
        showBanner();
    });

    // Safari iOS : aucune invite programmable → afficher le mode d'emploi après un court délai.
    if (isIos()) {
        window.addEventListener('load', () => setTimeout(showBanner, 2500));
    }

    window.addEventListener('appinstalled', () => {
        deferredPrompt = null;
        hideBanner(false);
    });

    document.addEventListener('click', (event) => {
        const installBtn = event.target.closest('[data-pwa-install]');
        if (installBtn) {
            if (!deferredPrompt) {
                return;
            }
            deferredPrompt.prompt();
            deferredPrompt.userChoice.then(() => {
                deferredPrompt = null;
                hideBanner(true);
            }).catch(() => {});
            return;
        }
        if (event.target.closest('[data-pwa-dismiss]')) {
            hideBanner(true);
        }
    });
})();

