 1 | /* Service Worker — Les Rois du Sahel (PWA).
 2 |  *
 3 |  * Stratégie volontairement prudente pour une application authentifiée :
 4 |  * - navigations : réseau d'abord, repli sur la page /offline (puis cache) ;
 5 |  * - assets statiques (build, images, icônes, polices) : cache d'abord, réactualisé en arrière-plan ;
 6 |  * - tout le reste (POST, API/XHR, origines tierces) : jamais intercepté.
 7 |  *
 8 |  * Incrémenter PWA_CACHE_VERSION à chaque déploiement modifiant le shell statique.
 9 |  */
10 | const PWA_CACHE_VERSION = 'rds-pwa-v1';
11 | const STATIC_CACHE = 'rds-static-' + PWA_CACHE_VERSION;
12 | const OFFLINE_URL = '/offline';
13 | const PRECACHE_URLS = [OFFLINE_URL, '/images/logo_roi.jpeg', '/icons/icon-192x192.png'];
14 | 
15 | self.addEventListener('install', (event) => {
16 |     event.waitUntil(
17 |         caches.open(STATIC_CACHE).then((cache) => cache.addAll(PRECACHE_URLS)).then(() => self.skipWaiting())
18 |     );
19 | });
20 | 
21 | self.addEventListener('activate', (event) => {
22 |     event.waitUntil(
23 |         caches
24 |             .keys()
25 |             .then((keys) => Promise.all(keys.filter((key) => key !== STATIC_CACHE).map((key) => caches.delete(key))))
26 |             .then(() => self.clients.claim())
27 |     );
28 | });
29 | 
30 | function isStaticAsset(url) {
31 |     if (url.pathname.startsWith('/build/') || url.pathname.startsWith('/icons/') || url.pathname.startsWith('/images/')) {
32 |         return true;
33 |     }
34 | 
35 |     return /\.(?:css|js|png|jpe?g|webp|svg|ico|woff2?|ttf|eot)$/i.test(url.pathname);
36 | }
37 | 
38 | self.addEventListener('fetch', (event) => {
39 |     const { request } = event;
40 | 
41 |     if (request.method !== 'GET') {
42 |         return;
43 |     }
44 | 
45 |     const url = new URL(request.url);
46 | 
47 |     if (url.origin !== self.location.origin) {
48 |         return;
49 |     }
50 | 
51 |     // Navigations : réseau d'abord pour ne jamais servir de page authentifiée périmée.
52 |     if (request.mode === 'navigate') {
53 |         event.respondWith(
54 |             fetch(request)
55 |                 .then((response) => {
56 |                     const copy = response.clone();
57 |                     caches.open(STATIC_CACHE).then((cache) => cache.put(request, copy)).catch(() => {});
58 |                     return response;
59 |                 })
60 |                 .catch(() => caches.match(request).then((hit) => hit || caches.match(OFFLINE_URL)))
61 |         );
62 |         return;
63 |     }
64 | 
65 |     // Assets statiques : réponse immédiate depuis le cache, réactualisation en arrière-plan.
66 |     if (isStaticAsset(url)) {
67 |         event.respondWith(
68 |             caches.match(request).then((hit) => {
69 |                 const network = fetch(request)
70 |                     .then((response) => {
71 |                         if (response && response.ok) {
72 |                             const copy = response.clone();
73 |                             caches.open(STATIC_CACHE).then((cache) => cache.put(request, copy)).catch(() => {});
74 |                         }
75 |                         return response;
76 |                     })
77 |                     .catch(() => hit);
78 |                 return hit || network;
79 |             })
80 |         );
81 |     }
82 | });

