public function create(Request $request): View
{
    $activeYear = AcademicYear::getActive();
    $classes = SchoolClass::with('level.cycle')
        ->where('academic_year_id', $activeYear?->id ?? 0)
        ->get();

    $selectedClassId = $request->query('class_id', $classes->first()?->id);
    $date = $request->query('date', date('Y-m-d'));
    $session = $request->query('session', 'MATIN');
    $subjectId = $request->query('subject_id');

    $subjects = Subject::orderBy('name')->get();

    // --- AUTO-SELECTION POUR ENSEIGNANT ---
    $teacherAssignments = $this->teacherAssignments();
    if ($teacherAssignments) {
        // Par défaut on prend la première classe et la première matière de l'enseignant
        // L'utilisateur peut bien sûr les changer dans le formulaire
        $selectedClassId = $teacherAssignments['classes']->isNotEmpty() 
            ? $teacherAssignments['classes']->first() 
            : $selectedClassId;
        $subjectId = $teacherAssignments['subjects']->isNotEmpty() 
            ? $teacherAssignments['subjects']->first() 
            : $subjectId;
    }

    $selectedClass = $classes->firstWhere('id', $selectedClassId);

    // Fetch students enrolled in this class
    $students = collect();
    if ($selectedClassId) {
        $students = Student::whereHas('enrollments', function ($q) use ($selectedClassId, $activeYear) {
            $q->where('class_id', $selectedClassId)
                ->where('academic_year_id', $activeYear?->id ?? 0)
                ->where('status', 'VALIDE');
        })
            ->with(['attendances' => function ($q) use ($selectedClassId, $date, $session, $subjectId) {
                $q->where('class_id', $selectedClassId)
                    ->where('attendance_date', $date)
                    ->where('session', $session)
                    ->when($subjectId, fn ($sq) => $sq->where('subject_id', $subjectId));
            }])
            ->orderBy('last_name')
            ->orderBy('first_name')
            ->get();
    }

    return view('attendances.create', compact(
        'classes',
        'selectedClass',
        'selectedClassId',
        'date',
        'session',
        'subjectId',
        'subjects',
        'students',
        'activeYear',
        'teacherAssignments'
    ));
}

