            'attendance_date.before_or_equal' => "La date de présence ne peut pas dépasser le {$activeYear->end_date->format('d/m/Y')} (fin de l'année scolaire) ni être future.",
            'attendance_date.after_or_equal' => "La date de présence doit être postérieure au {$activeYear->start_date->format('d/m/Y')} (début de l'année scolaire).",
